// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 fuzzValue, uint256 fuzzBlockNumber, uint256 fuzzTimestamp) public {
        fuzzValue = bound(fuzzValue, 10 ether, 10 ether);
        vm.assume(fuzzTimestamp > 0);
        vm.assume(fuzzBlockNumber < type(uint256).max);

        vm.roll(fuzzBlockNumber);
        vm.warp(fuzzTimestamp);

        address actor = address(0x1234);
        vm.deal(actor, fuzzValue);
        vm.prank(actor);
        (bool success,) = address(c).call{value: fuzzValue}("");
        require(success, "fallback call failed");

        assertEq(c.pastBlockTime(), block.timestamp + 1, "pastBlockTime must be block.timestamp + 1");
    }
}
